import { randomBytes } from "crypto";
import { mkdir, writeFile, unlink } from "fs/promises";
import path from "path";

const UPLOAD_DIR = process.env.UPLOAD_DIR ?? "./uploads";

export const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20 MB

export function uploadRoot() {
  return path.resolve(process.cwd(), UPLOAD_DIR);
}

export function storagePath(fileName: string) {
  // `fileName` is generated by us, but normalise anyway so a crafted value
  // can never escape the upload directory.
  const safe = path.basename(fileName);
  return path.join(uploadRoot(), safe);
}

export async function saveUpload(file: File) {
  if (file.size === 0) throw new Error("File is empty");
  if (file.size > MAX_FILE_SIZE) {
    throw new Error(`File exceeds ${MAX_FILE_SIZE / 1024 / 1024} MB`);
  }

  const ext = path
    .extname(file.name)
    .slice(0, 12)
    .replace(/[^a-zA-Z0-9.]/g, "");
  const fileName = `${Date.now()}-${randomBytes(8).toString("hex")}${ext}`;

  await mkdir(uploadRoot(), { recursive: true });
  const bytes = Buffer.from(await file.arrayBuffer());
  await writeFile(storagePath(fileName), bytes);

  return {
    fileName,
    originalName: file.name.slice(0, 200),
    mimeType: file.type || "application/octet-stream",
    size: file.size,
  };
}

export async function deleteUpload(fileName: string) {
  try {
    await unlink(storagePath(fileName));
  } catch {
    // Already gone — deleting the DB row is what matters.
  }
}

// `formatBytes` now lives in lib/media.ts so client components can use it
// without dragging the filesystem imports above into the browser bundle.
export { formatBytes } from "./media";
